package com.pranit.productsupport.core.api;
import com.pranit.productsupport.contracts.*;import com.pranit.productsupport.core.domain.UserRole;import com.pranit.productsupport.core.service.TicketService;import jakarta.validation.Valid;import java.util.List;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/internal/v1") public class TicketController {private final TicketService service;public TicketController(TicketService s){service=s;}
 @PostMapping("/tickets") @ResponseStatus(HttpStatus.CREATED) public TicketResponse create(@AuthenticationPrincipal Jwt jwt,@RequestHeader("Idempotency-Key") String key,@Valid @RequestBody CreateTicketRequest r){return service.create(uid(jwt),key,r);}
 @GetMapping("/tickets/me") public TicketPageResponse mine(@AuthenticationPrincipal Jwt jwt,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){return service.myTickets(uid(jwt),page,size);}
 @GetMapping("/support/tickets") @PreAuthorize("hasAnyRole('SUPPORT_AGENT','ADMIN')") public TicketPageResponse queue(@RequestParam(required=false) TicketStatus status,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){return service.queue(status,page,size);}
 @PatchMapping("/tickets/{id}/assignment") @PreAuthorize("hasAnyRole('SUPPORT_AGENT','ADMIN')") public TicketResponse assign(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@Valid @RequestBody AssignTicketRequest r){return service.assign(id,uid(jwt),r.supportAgentId());}
 @GetMapping("/tickets/{id}") public TicketResponse get(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id){return service.get(id,uid(jwt),support(jwt));}
 @PostMapping("/tickets/{id}/comments") @ResponseStatus(HttpStatus.CREATED) public CommentResponse comment(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@Valid @RequestBody CreateCommentRequest r){return service.addComment(id,uid(jwt),role(jwt),r.content());}
 @GetMapping("/tickets/{id}/comments") public List<CommentResponse> comments(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id){return service.comments(id,uid(jwt),support(jwt));}
 @PatchMapping("/tickets/{id}/status") @PreAuthorize("hasAnyRole('SUPPORT_AGENT','ADMIN')") public TicketResponse status(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@Valid @RequestBody UpdateTicketStatusRequest r){return service.updateStatus(id,uid(jwt),r.status(),r.note());}
 @PostMapping("/tickets/{id}/quotes") @PreAuthorize("hasAnyRole('SUPPORT_AGENT','ADMIN')") @ResponseStatus(HttpStatus.CREATED) public QuoteResponse quote(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@Valid @RequestBody CreateQuoteRequest r){return service.createQuote(id,uid(jwt),r);}
 @GetMapping("/quotes/{id}") public QuoteResponse getQuote(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id){return service.getQuote(id,uid(jwt),support(jwt));}
 private Long uid(Jwt jwt){return Long.valueOf(jwt.getSubject());} private UserRole role(Jwt jwt){List<String> r=jwt.getClaimAsStringList("roles");if(r==null||r.isEmpty())return UserRole.CUSTOMER;return UserRole.valueOf(r.get(0).replace("ROLE_",""));} private boolean support(Jwt jwt){UserRole r=role(jwt);return r==UserRole.ADMIN||r==UserRole.SUPPORT_AGENT;}
}
